WITH remaining_keys AS (SELECT product_id FROM order_items INTERSECT ALL SELECT product_id FROM order_items WHERE quantity >= 4), reconciled AS (SELECT s.* FROM order_items s JOIN remaining_keys k ON s.product_id = k.product_id) SELECT CASE WHEN quantity >= 8 THEN 'HIGH' ELSE 'LOW' END AS quantity_tier, CASE WHEN unit_price >= 430 THEN 'HIGH' ELSE 'LOW' END AS unit_price_tier, ROUND(AVG(unit_price), 2) AS avg_unit_price, CORR(quantity, unit_price) AS corr_quantity_unit_price FROM reconciled GROUP BY CASE WHEN quantity >= 8 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN unit_price >= 430 THEN 'HIGH' ELSE 'LOW' END ORDER BY avg_unit_price DESC NULLS LAST;
